#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    long long stock, amount;
    int q;
    scanf("%lld%d", &stock, &q);
    for (int i = 0; i < q; ++i) {
        char operation[4];
        scanf("%3s%lld", operation, &amount);
        if (strcmp(operation, "IN") == 0) {
            stock += amount;
            printf("%lld\n", stock);
        } else if (stock >= amount) {
            stock -= amount;
            printf("%lld\n", stock);
        } else {
            printf("-1\n");
        }
    }
    return 0;
}

